import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"專案能力現況：版號、多語系、無障礙","description":"","frontmatter":{},"headers":[],"relativePath":"CAPABILITIES.md","filePath":"CAPABILITIES.md"}'),n={name:"CAPABILITIES.md"};function i(c,e,d,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="專案能力現況-版號、多語系、無障礙" tabindex="-1">專案能力現況：版號、多語系、無障礙 <a class="header-anchor" href="#專案能力現況-版號、多語系、無障礙" aria-label="Permalink to &quot;專案能力現況：版號、多語系、無障礙&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>本文件說明專案在<strong>打版號、多語系、無障礙</strong>的現況與可選改進，供協作與規劃參考。<br> （與根目錄 <strong>AGENT_CAPABILITIES.md</strong> 不同：該檔為 agent 能力邊界與 agent class；本檔為產品／技術能力現況。）</p><hr><h2 id="_1-打版號-versioning" tabindex="-1">1. 打版號（Versioning） <a class="header-anchor" href="#_1-打版號-versioning" aria-label="Permalink to &quot;1. 打版號（Versioning）&quot;">​</a></h2><h3 id="現況-有流程-無-ui-顯示" tabindex="-1">現況：有流程，無 UI 顯示 <a class="header-anchor" href="#現況-有流程-無-ui-顯示" aria-label="Permalink to &quot;現況：有流程，無 UI 顯示&quot;">​</a></h3><ul><li><strong>有</strong>：使用 <strong>Changesets</strong>（<code>@changesets/cli</code>）管理版本與 CHANGELOG。 <ul><li>PR 內執行 <code>pnpm run changeset</code> 選擇變更類型（major/minor/patch）並填寫說明。</li><li>發版時在 main 上執行 <code>pnpm run changeset:version</code>（更新版號與 CHANGELOG）、<code>pnpm run changeset:publish</code>（若為可發佈套件）。</li><li>詳見 <code>docs/DEVELOPMENT.md</code>。</li></ul></li><li><strong>沒有</strong>：專案為 <code>&quot;private&quot;: true</code>，沒有在 <strong>UI 上顯示版號</strong>（例如 footer 的「v1.2.3」）。</li></ul><h3 id="可選改進" tabindex="-1">可選改進 <a class="header-anchor" href="#可選改進" aria-label="Permalink to &quot;可選改進&quot;">​</a></h3><ul><li><strong>在頁面顯示版號</strong>：建置時將版號注入環境變數或 JSON，root 或 footer 讀取並顯示（例如從 <code>package.json</code> 的 <code>version</code> 或 Vercel 的 <code>VERCEL_GIT_COMMIT_SHA</code> 簡短版）。</li><li><strong>Release 流程</strong>：可加 GitHub Action 在 main 合併 changeset 後自動跑 <code>changeset version</code> 並 commit，或手動發版。</li></ul><hr><h2 id="_2-多語系-i18n" tabindex="-1">2. 多語系（i18n） <a class="header-anchor" href="#_2-多語系-i18n" aria-label="Permalink to &quot;2. 多語系（i18n）&quot;">​</a></h2><h3 id="現況-有-手動字典" tabindex="-1">現況：有（手動字典） <a class="header-anchor" href="#現況-有-手動字典" aria-label="Permalink to &quot;現況：有（手動字典）&quot;">​</a></h3><ul><li>Cookie / Accept-Language locale（<code>zh-TW</code> · <code>en</code>）。</li><li>翻譯在 <code>app/shared/i18n/translations/*.json</code>；<code>{year}</code> / <code>{version}</code> 等 placeholder 於 runtime 插值。</li><li><strong>版權年</strong>勿寫死：<code>footer.copyright</code> 用 <code>© {year} …</code> + <code>new Date().getFullYear()</code>。</li></ul><hr><h2 id="_3-無障礙-accessibility-a11y" tabindex="-1">3. 無障礙（Accessibility / a11y） <a class="header-anchor" href="#_3-無障礙-accessibility-a11y" aria-label="Permalink to &quot;3. 無障礙（Accessibility / a11y）&quot;">​</a></h2><h3 id="現況-chat-a11y-語音輸入已上線-t-2026-078" tabindex="-1">現況：chat a11y + 語音輸入已上線（T-2026-078） <a class="header-anchor" href="#現況-chat-a11y-語音輸入已上線-t-2026-078" aria-label="Permalink to &quot;現況：chat a11y + 語音輸入已上線（T-2026-078）&quot;">​</a></h3><ul><li><strong>有</strong>：<code>&lt;html lang&gt;</code>；skip link <code>a11y.skipToContent</code> → <code>#main-content</code>；<code>eslint-plugin-jsx-a11y</code>；Radix / Alert ARIA（錯誤 <code>role=&quot;alert&quot;</code>）；chat history <code>role=&quot;log&quot;</code> + polite live region（串流中只公告等待，完成後公告摘要／全文，避免 token 洗版）；composer 送出與麥克風皆有 <code>aria-label</code>。</li><li><strong>語音</strong>：共用 <code>Composer</code> 在 <code>SpeechRecognition</code>／<code>webkitSpeechRecognition</code> 可用時顯示麥克風；權限拒絕或不支援不擋鍵盤；辨識結果填入輸入框，由使用者按送出。文案鍵 <code>composer.voice.*</code>。</li><li><strong>規劃</strong>：<a href="./product/a11y-voice-plan.html">docs/product/a11y-voice-plan.md</a>（Phase 3 TTS 仍未做）。</li></ul><hr><h2 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to &quot;總結&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>現況</th><th>建議</th></tr></thead><tbody><tr><td><strong>打版號</strong></td><td>Changesets + footer version</td><td>維持</td></tr><tr><td><strong>多語系</strong></td><td>手動字典 + locale 切換</td><td>版權與 UI 文案皆走 i18n</td></tr><tr><td><strong>無障礙</strong></td><td>skip link、chat live、composer 語音</td><td>TTS 為後續；axe 抽檢維持</td></tr></tbody></table>',20)])])}const p=o(n,[["render",i]]);export{u as __pageData,p as default};
